INSERT INTO _migration_508_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_proverbs_s2_001', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is an “abɛ” in Akan speech?', 'multiple_choice', NULL, '["A. A proverb — a short, wise saying","B. A folktale about Ananse","C. A funeral dirge","D. A praise song"]', 'A', 'Abɛ is the Akan word for a proverb, a short traditional saying that carries wisdom. Folktales are anansesem, while dirges and praise songs are performed pieces, not proverbs. Therefore the correct answer is A: A proverb — a short, wise saying.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_002', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The proverb “Tikoro nko agyina” teaches which lesson?', 'multiple_choice', NULL, '["A. It is best to stand alone in every matter","B. One person alone cannot hold council — unity and cooperation are needed","C. A leader needs no advice from anyone","D. Meetings are a waste of time"]', 'B', 'Tikoro nko agyina literally means “one head does not go into council”: important decisions need more than one mind. It teaches the value of cooperation and consultation, the opposite of standing alone. Therefore the correct answer is B: One person alone cannot hold council — unity and cooperation are needed.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_003', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Why do Akan speakers value proverbs in everyday speech?', 'multiple_choice', NULL, '["A. They make speech longer without adding meaning","B. They are used only to insult listeners","C. They pass on wisdom and advice in a memorable, indirect way","D. They completely replace ordinary greetings"]', 'C', 'Proverbs package the community’s wisdom into short, memorable sayings, allowing speakers to advise or correct others politely and indirectly. Skilful use of proverbs is a mark of a good speaker in Akan culture. Therefore the correct answer is C: They pass on wisdom and advice in a memorable, indirect way.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_004', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, '“Woforo dua pa a, na yɛpia wo” means what?', 'multiple_choice', NULL, '["A. Never climb trees without permission","B. Good trees belong only to the elders","C. You should never ask anyone for help","D. If you climb a good tree, we give you a push — society supports a worthy cause"]', 'D', 'The proverb says that when you climb a good tree, people push you up: when a person pursues a good and worthy goal, the community rallies to support them. It encourages worthwhile effort rather than forbidding climbing or help. Therefore the correct answer is D: If you climb a good tree, we give you a push — society supports a worthy cause.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_005', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The saying behind Sankofa — “Sɛ wo were fi na wosan kɔ fa a, yɛnkyiri” — teaches that...', 'multiple_choice', NULL, '["A. It is not wrong to go back for what you have forgotten — we should learn from the past","B. The past must be forgotten completely","C. You should never turn back on a journey","D. Old things are always useless"]', 'A', 'The Sankofa saying means “it is not taboo to go back and fetch what you forgot”: revisiting the past to recover wisdom is honourable, not shameful. This is why the Sankofa bird looks backwards, and it is the opposite of forgetting the past. Therefore the correct answer is A: It is not wrong to go back for what you have forgotten — we should learn from the past.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_006', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, '“Aboa bi bɛka wo a, na ofiri wo ntoma mu” warns that...', 'multiple_choice', NULL, '["A. Insects like hiding inside clothes","B. Danger or betrayal can come from people who are very close to you","C. Only strangers can ever hurt you","D. You should never wear other people’s clothes"]', 'B', 'Literally, “the insect that will bite you comes from your own cloth”: the people closest to us are often the ones in a position to harm or betray us. The cloth and the insect are images, so the literal readings are distractors. Therefore the correct answer is B: Danger or betrayal can come from people who are very close to you.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_007', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The proverb “Obi nkyere abɔfra Nyame” (no one points out God to a child) suggests what?', 'multiple_choice', NULL, '["A. Children must never be taught about religion","B. God reveals Himself only to adults","C. Some truths are so evident that they need no explanation","D. Children always know more than elders"]', 'C', 'The proverb means that no one has to show God to a child, because the evidence of God in creation is plain for all to see: some truths are self-evident. It does not forbid religious teaching or claim children know more than elders. Therefore the correct answer is C: Some truths are so evident that they need no explanation.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bghl_proverbs_s2_008', 'topic_bece_ghlang_proverbs', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'How does an idiom (nsɛnkyerɛnne) differ from a proverb?', 'multiple_choice', NULL, '["A. An idiom is always longer than a proverb","B. Idioms are used only in written Twi","C. There is no difference between the two","D. An idiom is a fixed phrase whose meaning cannot be worked out from its individual words, while a proverb is a complete wise saying"]', 'D', 'An idiom is a fixed expression with a figurative meaning that its separate words do not reveal, whereas a proverb is a full traditional saying that states a piece of wisdom. Both are used freely in spoken Twi, and length is not what separates them. Therefore the correct answer is D: An idiom is a fixed phrase whose meaning cannot be worked out from its individual words, while a proverb is a complete wise saying.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_508_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_508_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_508_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_508_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_508_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_508_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_508_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_508_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_508_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_508_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
